50	func wantHash(seq int64, account, operation, resource, result, occurredAt, prevHash string) string {
51		// Mirror the store's escaping: backslash and double quote are escaped,
52		// everything else in these test inputs stays raw.
53		escape := func(s string) string {
54			return strings.NewReplacer(`\`, `\\`, `"`, `\"`).Replace(s)
55		}
56		payload := fmt.Sprintf(`[%d,"%s","%s","%s","%s","%s","%s"]`, seq,
57			escape(account), escape(operation), escape(resource), escape(result), escape(occurredAt), escape(prevHash))
58		sum := sha256.Sum256([]byte(payload))
59		return hex.EncodeToString(sum[:])
60	}
