315	// wantInvalidInput posts one event body and asserts the invalid_audit_input
316	// rejection shape: 400, only a top-level error object, and no internals.
317	func wantInvalidInput(t *testing.T, router http.Handler, body string) {
318		t.Helper()
319		recorder := postEventBody(t, router, body)
320		if recorder.Code != http.StatusBadRequest {
321			t.Fatalf("status = %d, want %d (%s)", recorder.Code, http.StatusBadRequest, recorder.Body.String())
322		}
323		decoded := decodeEvent(t, recorder)
324		if len(decoded) != 1 {
325			t.Fatalf("response keys = %v, want only the error object", decoded)
326		}
327		errObj, ok := decoded["error"].(map[string]any)
328		if !ok {
329			t.Fatalf("error = %v, want an object", decoded["error"])
330		}
331		if errObj["code"] != "invalid_audit_input" {
332			t.Fatalf("code = %v, want invalid_audit_input", errObj["code"])
333		}
334		if message, ok := errObj["message"].(string); !ok || message == "" {
335			t.Fatalf("message = %v, want a non-empty string", errObj["message"])
336		}
337		leaks := []string{"sql", "SELECT", "INSERT", "goroutine", ".go", "/", "\\"}
338		for _, leak := range leaks {
339			if strings.Contains(recorder.Body.String(), leak) {
340				t.Fatalf("response leaks internals (%q): %s", leak, recorder.Body.String())
341			}
342		}
343	}
