484			t.Fatalf("stored event = %+v, want the valid append", stored[0])
485		}
486	
487		// After a close and reopen the chain continues from the same tail.
488		st, err = store.Open(path)
489		if err != nil {
490			t.Fatalf("reopen: %v", err)
491		}
492		defer st.Close()
493		second := decodeEvent(t, postEventBody(t, NewRouter(st), validEventBody()))
494		if second["seq"] != float64(2) || second["prev_hash"] != first["hash"] {
495			t.Fatalf("after reopen: seq = %v prev_hash = %v, want 2 and %v", second["seq"], second["prev_hash"], first["hash"])
496		}
497		stored = readStoredEvents(t, path)
498		if len(stored) != 2 || stored[1].hash != second["hash"] {
499			t.Fatalf("stored events after reopen = %+v", stored)
500		}
501	}
502	
503	func TestPostEventRejectsInvalidUTF8(t *testing.T) {
504		cases := map[string]string{
505			"invalid byte in value":     `{"account":"a` + "\xff" + `","operation":"o","resource":"r","result":"ok","occurred_at":"2026-10-05T00:00:00Z"}`,
506			"truncated multibyte value": `{"account":"` + "\xe4\xb8" + `","operation":"o","resource":"r","result":"ok","occurred_at":"2026-10-05T00:00:00Z"}`,
507			"invalid byte in key":       `{"acc` + "\xff" + `ount":"a","operation":"o","resource":"r","result":"ok","occurred_at":"2026-10-05T00:00:00Z"}`,
508			"overlong encoding":         `{"account":"` + "\xc0\xaf" + `","operation":"o","resource":"r","result":"ok","occurred_at":"2026-10-05T00:00:00Z"}`,
509			"utf8 encoded surrogate":    `{"account":"` + "\xed\xa0\x80" + `","operation":"o","resource":"r","result":"ok","occurred_at":"2026-10-05T00:00:00Z"}`,
510		}
511		for name, body := range cases {
512			t.Run(name, func(t *testing.T) {
513				router := NewRouter(openTestStore(t))
514				wantInvalidInput(t, router, body)
515			})
516		}
517	}
518	
519	func TestPostEventRejectsUnpairedSurrogates(t *testing.T) {
520		cases := map[string]string{
521			"lone high surrogate":       `{"account":"\uD83D","operation":"o","resource":"r","result":"ok","occurred_at":"2026-10-05T00:00:00Z"}`,
522			"lone low surrogate":        `{"account":"\uDE00","operation":"o","resource":"r","result":"ok","occurred_at":"2026-10-05T00:00:00Z"}`,
523			"reversed pair":             `{"account":"\uDE00\uD83D","operation":"o","resource":"r","result":"ok","occurred_at":"2026-10-05T00:00:00Z"}`,
524			"high then non surrogate":   `{"account":"\uD83DA","operation":"o","resource":"r","result":"ok","occurred_at":"2026-10-05T00:00:00Z"}`,
525			"high at end of string":     `{"account":"a\uD83D","operation":"o","resource":"r","result":"ok","occurred_at":"2026-10-05T00:00:00Z"}`,
526			"surrogates across strings": `{"account":"\uD83D","operation":"\uDE00","resource":"r","result":"ok","occurred_at":"2026-10-05T00:00:00Z"}`,
527			"lowercase hex":             `{"account":"\ud83d","operation":"o","resource":"r","result":"ok","occurred_at":"2026-10-05T00:00:00Z"}`,
528			"surrogate in occurred_at":  `{"account":"a","operation":"o","resource":"r","result":"ok","occurred_at":"2026-10-05T00:00:00Z\uD83D"}`,
529		}
530		for name, body := range cases {
531			t.Run(name, func(t *testing.T) {
532				router := NewRouter(openTestStore(t))
533				wantInvalidInput(t, router, body)
534			})
535		}
536	}
