538	func TestPostEventAcceptsValidUnicode(t *testing.T) {
539		path := filepath.Join(t.TempDir(), "service.db")
540		st, err := store.Open(path)
541		if err != nil {
542			t.Fatalf("open: %v", err)
543		}
544		defer st.Close()
545		router := NewRouter(st)
546	
547		cases := []struct {
548			name        string
549			accountJSON string // JSON literal used for the account field
550			wantAccount string // decoded text the ledger must store verbatim
551		}{
552			{"direct chinese", `"账号"`, "账号"},
553			{"escaped chinese", `"\u8d26\u53f7"`, "账号"},
554			{"direct supplementary plane", `"😀"`, "😀"},
555			{"escaped supplementary plane", `"\uD83D\uDE00"`, "😀"},
556			{"escaped supplementary plane lowercase", `"\ud83d\ude00"`, "😀"},
557			{"direct replacement char", `"�"`, "�"},
558			{"escaped replacement char", `"\ufffd"`, "�"},
559			{"escaped backslash text", `"\\uD83D"`, `\uD83D`},
560		}
561		prevHash := strings.Repeat("0", 64)
562		for i, tc := range cases {
563			body := `{"account":` + tc.accountJSON + `,"operation":"o","resource":"r","result":"ok","occurred_at":"2026-10-05T00:00:00Z"}`
564			recorder := postEventBody(t, router, body)
565			if recorder.Code != http.StatusCreated {
566				t.Fatalf("%s: status = %d (%s)", tc.name, recorder.Code, recorder.Body.String())
567			}
568			event := decodeEvent(t, recorder)
569			if event["account"] != tc.wantAccount {
570				t.Fatalf("%s: account = %q, want %q", tc.name, event["account"], tc.wantAccount)
571			}
572			// The hash is computed over the decoded text, so an escaped
573			// surrogate pair and the same character submitted directly
574			// produce identical hashes at identical chain positions.
575			seq := int64(i + 1)
576			want := wantHash(seq, tc.wantAccount, "o", "r", "ok", "2026-10-05T00:00:00Z", prevHash)
577			if event["hash"] != want {
578				t.Fatalf("%s: hash = %v, want %v", tc.name, event["hash"], want)
579			}
580			prevHash = event["hash"].(string)
581		}
582	
583		// What was persisted matches the decoded text exactly.
584		stored := readStoredEvents(t, path)
585		if len(stored) != len(cases) {
586			t.Fatalf("stored %d events, want %d", len(stored), len(cases))
587		}
588		for i, tc := range cases {
589			if stored[i].account != tc.wantAccount {
590				t.Fatalf("%s: stored account = %q, want %q", tc.name, stored[i].account, tc.wantAccount)
591			}
592		}
593	}
