30		"github.com/xjeey8iust/sen-audit-ledger/internal/store"
31	)
32	
33	// createdEvent is the typed 201 response body.
34	type createdEvent struct {
35		Account    string `json:"account"`
36		Operation  string `json:"operation"`
37		Resource   string `json:"resource"`
38		Result     string `json:"result"`
39		OccurredAt string `json:"occurred_at"`
40		Seq        int64  `json:"seq"`
41		PrevHash   string `json:"prev_hash"`
42		Hash       string `json:"hash"`
43	}
