240	func getHealthz(t *testing.T, router http.Handler) *httptest.ResponseRecorder {
241		t.Helper()
242		recorder := httptest.NewRecorder()
243		router.ServeHTTP(recorder, httptest.NewRequest(http.MethodGet, "/healthz", nil))
244		return recorder
245	}
