247	// setInsertFailure installs (or removes) a trigger that fails every INSERT
248	// on the events table while SELECTs and Ping keep working. It is installed
249	// from a connection the service does not own, so the product code stays
250	// unchanged and reads remain available throughout.
251	func setInsertFailure(t *testing.T, path string, enabled bool) {
252		t.Helper()
253		statement := "DROP TRIGGER IF EXISTS events_block_insert"
254		if enabled {
255			statement = `CREATE TRIGGER events_block_insert
256				BEFORE INSERT ON events
257				BEGIN
258					SELECT RAISE(FAIL, 'controlled write failure injected by regression test');
259				END;`
260		}
261		db, err := sql.Open("sqlite", path)
262		if err != nil {
263			t.Fatalf("open control connection: %v", err)
264		}
265		defer db.Close()
266		if _, err := db.Exec(statement); err != nil {
267			t.Fatalf("toggle insert failure (%v): %v", enabled, err)
268		}
269	}
270	
271	// concurrentFixtures returns distinguishable legal events: mixed offsets
272	// (including cross-day/month/year conversions), varied fractional-second
273	// shapes, a double quote, a backslash and non-ASCII text.
274	func concurrentFixtures() []eventFixture {
275		return []eventFixture{
276			{eventRequest{Account: `alice "admin"`, Operation: "login", Resource: "console-00", Result: "ok", OccurredAt: "2026-10-05T08:30:00+08:00"}, "2026-10-05T00:30:00Z"},
277			{eventRequest{Account: `用户\甲`, Operation: "read", Resource: "console-01", Result: "ok", OccurredAt: "2026-10-04T23:00:00-02:00"}, "2026-10-05T01:00:00Z"},
278			{eventRequest{Account: "acct-02", Operation: "write", Resource: "console-02", Result: "denied", OccurredAt: "2026-03-01T00:15:00.25+05:30"}, "2026-02-28T18:45:00.25Z"},
279			{eventRequest{Account: "acct-03", Operation: "logout", Resource: "console-03", Result: "ok", OccurredAt: "2026-01-01T00:30:00.5+08:00"}, "2025-12-31T16:30:00.5Z"},
280			{eventRequest{Account: "acct-04", Operation: "delete", Resource: "console-04", Result: "error", OccurredAt: "2026-10-05T12:00:00.123456789Z"}, "2026-10-05T12:00:00.123456789Z"},
281			{eventRequest{Account: "acct-05", Operation: "grant", Resource: "console-05", Result: "ok", OccurredAt: "2026-09-30T23:59:59-00:30"}, "2026-10-01T00:29:59Z"},
282			{eventRequest{Account: "acct-06", Operation: "audit", Resource: "console-06", Result: "ok", OccurredAt: "2026-12-31T23:00:00.000+01:00"}, "2026-12-31T22:00:00.000Z"},
283			{eventRequest{Account: "acct-07", Operation: "export", Resource: "console-07", Result: "denied", OccurredAt: "2026-02-28T23:30:00+01:00"}, "2026-02-28T22:30:00Z"},
284		}
